import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import {QuickSet} from '../../components/quick-set';
import {ActivityEnergy} from '../../components/activity-energy';
import {NutritionTracker} from '../../components/nutrition';
import {BodyMeasurements} from '../../components/body-measurements';
import {WorkoutEnergyButton} from '../../components/workout-energy';
import {initialData,setOf,type Data} from '../../lib/training';
import '../../app/globals.css';
function Fixture(){const [d,setD]=useState<Data>(()=>({...initialData(),bodyMeasurements:[{id:'weight',date:'2026-09-13',weight:190,bodyFat:null}],activityEnergy:{templates:[],logs:[{id:'activity',name:'Jiu-Jitsu',date:'2026-09-13',durationMinutes:90,intensity:'Vigorous',met:8,energyWeightLb:190,caloriesBurned:600,calorieSource:'manual',notes:''}]},nutrition:{calorieTarget:null,proteinTarget:null,entries:[{id:'food',name:'Protein shake',date:'2026-09-13',calories:150,protein:30}]},workouts:[]}));const w=d.workouts[0];return <main style={{padding:16}}><p>Disposable local UI fixture — account saves tested separately</p>{!w?<button className="primary" onClick={()=>setD({...d,workouts:[{id:'workout',name:'QA workout',date:new Date().toISOString(),completed:false,difficulty:'Moderate',notes:'',entries:[{exerciseId:'bench',sets:[setOf(100,8),setOf(100,8),setOf(100,8)]},{exerciseId:'row',sets:[setOf(50,10),setOf(50,10),setOf(50,10)]}]}]})}>Start saved workout</button>:<><h1>{w.completed?'Completed history':'QA workout'}</h1>{w.entries.map(e=><section className="panel log-panel" key={e.exerciseId}><h2>{e.exerciseId}</h2>{e.sets.map((s,i)=><QuickSet key={s.id} set={s} index={i} exercise={e.exerciseId} next={!w.completed&&w.entries.flatMap(e=>e.sets).find(s=>s.status==='pending')?.id===s.id} onAdvance={()=>{}} onDelete={()=>{}} onPatch={p=>setD({...d,workouts:[{...w,entries:w.entries.map(x=>x===e?{...x,sets:x.sets.map(t=>t===s?{...s,...p}:t)}:x)}]})}/>)}</section>)}<WorkoutEnergyButton workout={w} onSave={energy=>setD({...d,workouts:[{...w,...energy,completed:true}]})}/></>}<ActivityEnergy data={d} onChange={setD}/><NutritionTracker value={d.nutrition} onChange={nutrition=>setD({...d,nutrition})}/><BodyMeasurements entries={d.bodyMeasurements} onChange={bodyMeasurements=>setD({...d,bodyMeasurements})}/></main>};createRoot(document.getElementById('root')!).render(<Fixture/>);
